using System;using System.IO;using System.Text;using System.Linq;using System.Threading;using System.Diagnostics;using System.Collections.Generic;using F=System.Windows.Forms;
namespace GearLab {
 static class VisibilityTests {
  static int checks;internal static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
  static Result Build(int kind){var p=Engine.Starter(kind);if(kind==3){p.Ratio=60;p.Overall=222.82;Engine.FitOverall(p);}var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Model.Valid,"valid model "+kind);return r;}
  static string Geometry(WpfScene scene){return string.Join(";",scene.Nodes.Select(n=>n.Part.Id+":"+(n.Surface.Geometry==null?"null":n.Surface.Geometry.Bounds.ToString(System.Globalization.CultureInfo.InvariantCulture))+":"+(n.Surface.Geometry==null?0:((System.Windows.Media.Media3D.MeshGeometry3D)n.Surface.Geometry).TriangleIndices.Count)+":"+(n.Cap.Geometry==null?0:((System.Windows.Media.Media3D.MeshGeometry3D)n.Cap.Geometry).TriangleIndices.Count)));}
  static void PixelsEqual(string first,string second){using(var a=new System.Drawing.Bitmap(first))using(var b=new System.Drawing.Bitmap(second)){Check(a.Size==b.Size,"image dimensions");int changed=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))changed++;Check(changed==0,"restored picture differs at "+changed+" pixels");}}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   for(int kind=0;kind<4;kind++){var r=Build(kind);using(var scene=new WpfScene()){
     foreach(var part in r.Model.Parts)scene.Hidden.Add(part.Id);scene.SetResult(r,false);scene.Hidden.Clear();scene.RefreshVisibility();scene.UpdatePose(0);Check(scene.Nodes.All(n=>ReferenceEquals(n.Surface.Geometry,n.Frozen)),"initially hidden components failed to return, kind="+kind);
     scene.SavePng(Path.Combine(folder,"kind-"+kind+"-before.png"),700,540);int builds=SceneMesher.Builds;var centre=scene.Camera.Target;double width=scene.Camera.Width,yaw=scene.Camera.Yaw;
     for(int j=0;j<30;j++){foreach(var n in scene.Nodes)if(j%2==0||n.Part.Role=="housing")scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();scene.UpdatePose(j*.03);scene.Hidden.Clear();scene.RefreshVisibility();scene.UpdatePose(0);Check(scene.Nodes.All(n=>ReferenceEquals(n.Surface.Geometry,n.Frozen)),"hide/show lost geometry "+kind+"/"+j);}
     scene.SavePng(Path.Combine(folder,"kind-"+kind+"-restored.png"),700,540);PixelsEqual(Path.Combine(folder,"kind-"+kind+"-before.png"),Path.Combine(folder,"kind-"+kind+"-restored.png"));Check(scene.Camera.Target==centre&&scene.Camera.Width==width&&scene.Camera.Yaw==yaw,"visibility moved camera");Check(SceneMesher.Builds==builds,"visibility rebuilt meshes");
     using(var reference=new WpfScene()){reference.SetResult(r,false);foreach(bool exploded in new[]{false,true})foreach(int axis in new[]{-1,2,0,1}){scene.Hidden.Clear();scene.SetExploded(exploded);reference.SetExploded(exploded);scene.ConfigureSection(axis,.371,false);reference.ConfigureSection(axis,.371,false);scene.UpdatePose(.63);reference.UpdatePose(.63);foreach(var n in scene.Nodes)scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();scene.ConfigureSection(2,7.125,true);scene.UpdatePose(1.27);scene.ConfigureSection(axis,.371,false);scene.Hidden.Clear();scene.RefreshVisibility();scene.UpdatePose(.63);Check(Geometry(scene)==Geometry(reference),"stale section after show "+kind+"/"+axis+"/"+exploded);}}
     scene.Hidden.Clear();scene.ConfigureSection(-1,0,false);foreach(var n in scene.Nodes)scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();var changed=Engine.Clone(r.P);changed.ModelFlange+=1;var updated=Engine.Calculate(changed);updated.Model=CadBuilder.Build(updated);scene.SetResult(updated,false);scene.Hidden.Clear();scene.RefreshVisibility();Check(scene.Nodes.All(n=>ReferenceEquals(n.Surface.Geometry,n.Frozen)),"hidden rebuild did not restore "+kind);
    }log.AppendLine("PASS kind "+kind+": initially hidden load; 30 hide/show cycles; pixel-identical restore; no mesh rebuild/camera reset; section X/Y/Z and exploded mode; rebuilding hidden geometry.");}
   using(var form=new MainForm(new TestDialogs()))form.VisibilityUiRegression(folder,log);
   log.AppendLine("PASS "+checks+" visibility assertions.");File.WriteAllText(Path.Combine(folder,"visibility-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"visibility-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
  internal static IEnumerable<F.Control> Controls(F.Control root){yield return root;foreach(F.Control child in root.Controls)foreach(var item in Controls(child))yield return item;}
  internal static void Ready(WpfScene scene){var wait=Stopwatch.StartNew();while(!scene.Ready&&wait.Elapsed.TotalSeconds<30){F.Application.DoEvents();Thread.Sleep(5);}Check(scene.Ready,"async scene completion: "+scene.Error);}
 }
 public partial class MainForm {
  internal void VisibilityUiRegression(string folder,StringBuilder log){Opacity=0;ShowInTaskbar=false;Show();animation.Stop();Apply(Engine.Starter(0),true);ShowFullModel();hideHousing.Checked=true;VisibilityTests.Ready(canvas.Viewer.Scene);var scene=canvas.Viewer.Scene;hideHousing.Checked=false;VisibilityTests.Check(scene.Nodes.All(n=>n.Surface.Geometry!=null),"toolbar hide before load/show");var tree=VisibilityTests.Controls(canvas.Viewer).OfType<F.TreeView>().Single();var group=tree.Nodes.Cast<F.TreeNode>().First(n=>n.Text=="Корпус и крышки");var leaf=group.Nodes[0];var id=(string)leaf.Tag;
   for(int j=0;j<30;j++){leaf.Checked=false;VisibilityTests.Check(scene.Hidden.Contains(id),"leaf hidden");leaf.Checked=true;VisibilityTests.Check(!scene.Hidden.Contains(id)&&scene.Nodes.First(n=>n.Part.Id==id).Surface.Geometry!=null,"leaf returns");VisibilityTests.Check(ReferenceEquals(group,tree.Nodes.Cast<F.TreeNode>().First(n=>n.Text=="Корпус и крышки")),"tree nodes replaced during check");hideHousing.Checked=true;hideHousing.Checked=false;VisibilityTests.Check(scene.Nodes.All(n=>n.Surface.Geometry!=null),"toolbar repeatedly restores");}
   group.Checked=false;VisibilityTests.Check(canvas.HideHousing&&hideHousing.Checked,"group syncs toolbar");group.Checked=true;VisibilityTests.Check(!canvas.HideHousing&&!hideHousing.Checked,"group restores toolbar");leaf.Checked=false;VisibilityTests.Check(!hideHousing.Checked,"partial housing group");VisibilityTests.Controls(canvas.Viewer).OfType<F.Button>().Single(b=>b.Text=="Показать всё").PerformClick();VisibilityTests.Check(scene.Hidden.Count==0&&tree.Nodes.Cast<F.TreeNode>().All(n=>n.Checked),"show all clears flags");
   hideHousing.Checked=true;numbers["ModelFlange"].Commit(7);calculate.PerformClick();VisibilityTests.Ready(scene);hideHousing.Checked=false;VisibilityTests.Check(scene.Nodes.All(n=>n.Surface.Geometry!=null),"toolbar restores after recalculation while hidden");kind.SelectedIndex=3;VisibilityTests.Ready(scene);VisibilityTests.Check(scene.Hidden.Count==0&&!hideHousing.Checked,"new type starts visible");closingApproved=true;Close();log.AppendLine("PASS native controls: toolbar toggles during loading, individual/group checkboxes, stable tree nodes, partial group sync, show all, recalculation while hidden, type change.");}
 }
}
